-- Runtime MySQL 8 / MariaDB schema. Separate from the original reference schema.
CREATE TABLE IF NOT EXISTS sg_lock (id INT PRIMARY KEY) ENGINE=InnoDB;
INSERT IGNORE INTO sg_lock VALUES (1);
CREATE TABLE IF NOT EXISTS sg_settings (name VARCHAR(100) PRIMARY KEY, value JSON NOT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS sg_users (id BIGINT UNSIGNED PRIMARY KEY, document JSON NOT NULL, email VARCHAR(190) GENERATED ALWAYS AS (JSON_UNQUOTE(JSON_EXTRACT(document, '$.email'))) STORED, UNIQUE KEY (email)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS sg_categories (id BIGINT UNSIGNED PRIMARY KEY, document JSON NOT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS sg_products (id BIGINT UNSIGNED PRIMARY KEY, document JSON NOT NULL, category_id BIGINT UNSIGNED GENERATED ALWAYS AS (JSON_EXTRACT(document, '$.category_id')) STORED, INDEX (category_id), FOREIGN KEY (category_id) REFERENCES sg_categories(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS sg_orders (id BIGINT UNSIGNED PRIMARY KEY, document JSON NOT NULL, user_id BIGINT UNSIGNED GENERATED ALWAYS AS (JSON_EXTRACT(document, '$.user_id')) STORED, INDEX (user_id), FOREIGN KEY (user_id) REFERENCES sg_users(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS sg_expenses (id BIGINT UNSIGNED PRIMARY KEY, document JSON NOT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS sg_incomes (id BIGINT UNSIGNED PRIMARY KEY, document JSON NOT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS sg_inventory_movements (id BIGINT UNSIGNED PRIMARY KEY, document JSON NOT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS sg_notifications (id BIGINT UNSIGNED PRIMARY KEY, document JSON NOT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS sg_user_account_events (id BIGINT UNSIGNED PRIMARY KEY, document JSON NOT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS sg_order_items (order_id BIGINT UNSIGNED NOT NULL, position INT NOT NULL, product_id BIGINT UNSIGNED NOT NULL, quantity INT NOT NULL, unit_price DECIMAL(12,2) NOT NULL, document JSON NOT NULL, PRIMARY KEY(order_id,position), FOREIGN KEY(order_id) REFERENCES sg_orders(id), FOREIGN KEY(product_id) REFERENCES sg_products(id)) ENGINE=InnoDB;
